    'Коррекция начинается, когда влажность в помещении превышает начальную влажность. Вентиляционная коррекция будет пропорциональна диапазону влажности. Пример: начальная влажность=50%, диапазон=10%, коррекция вентиляции=20% Влажность в помещении=55% Коррекция сделана на вентиляцию=10%.'
